const input = $input.first().json;
const body = input.body ?? input;
const rawImage = typeof body.imageBase64 === 'string' ? body.imageBase64 : '';
const imageBase64 = rawImage.replace(/^data:image\/[a-zA-Z0-9.+-]+;base64,/, '').trim();
const mimeType = typeof body.mimeType === 'string' && body.mimeType.startsWith('image/') ? body.mimeType : 'image/jpeg';

if (!imageBase64) {
  throw new Error('Falta el campo imageBase64 en la solicitud.');
}

const systemPrompt = `Eres un asistente experto en estimación nutricional visual para la app Nutri Lens.
Tu tarea es analizar UNA fotografía de alimentos o bebidas, identificar cada componente visible y estimar su porción en gramos, calorías (kcal), proteínas (g), carbohidratos (g) y grasas (g).

Reglas estrictas:
1. Responde SIEMPRE en español neutro para textos y nombres de alimentos.
2. Si la imagen NO contiene comida ni bebidas consumibles, devuelve is_food: false, dish_name: "No se detectó alimento", confidence: 0, todos los totales en 0 e items vacío.
3. Desglosa los ingredientes principales del platillo en el arreglo items.
4. Asegúrate de que total_calories, total_protein_g, total_carbs_g y total_fat_g coincidan con la suma de items.
5. Usa valores realistas basados en porciones estándar mexicanas e internacionales.
6. En notes incluye una observación breve sobre posibles ingredientes ocultos (ej. aceite, aderezo, mantequilla) si aplica. Nunca emitas diagnósticos médicos.`;

const geminiPayload = {
  system_instruction: {
    parts: [{ text: systemPrompt }]
  },
  contents: [
    {
      role: 'user',
      parts: [
        { text: 'Analiza este platillo y devuelve exclusivamente el JSON estructurado según el esquema.' },
        {
          inline_data: {
            mime_type: mimeType,
            data: imageBase64
          }
        }
      ]
    }
  ],
  generationConfig: {
    temperature: 0.2,
    responseMimeType: 'application/json',
    responseSchema: {
      type: 'OBJECT',
      properties: {
        is_food: { type: 'BOOLEAN' },
        dish_name: { type: 'STRING' },
        confidence: { type: 'INTEGER' },
        total_calories: { type: 'NUMBER' },
        total_protein_g: { type: 'NUMBER' },
        total_carbs_g: { type: 'NUMBER' },
        total_fat_g: { type: 'NUMBER' },
        notes: { type: 'STRING' },
        items: {
          type: 'ARRAY',
          items: {
            type: 'OBJECT',
            properties: {
              name: { type: 'STRING' },
              portion_grams: { type: 'NUMBER' },
              calories: { type: 'NUMBER' },
              protein_g: { type: 'NUMBER' },
              carbs_g: { type: 'NUMBER' },
              fat_g: { type: 'NUMBER' }
            },
            required: ['name', 'portion_grams', 'calories', 'protein_g', 'carbs_g', 'fat_g']
          }
        }
      },
      required: [
        'is_food',
        'dish_name',
        'confidence',
        'total_calories',
        'total_protein_g',
        'total_carbs_g',
        'total_fat_g',
        'notes',
        'items'
      ]
    }
  }
};

return [{ json: { geminiPayload } }];

const response = $input.first().json;
const rawText = response?.candidates?.[0]?.content?.parts?.[0]?.text;

if (!rawText) {
  throw new Error('Gemini no devolvió texto en la respuesta.');
}

const cleaned = rawText.replace(/^```json\s*/i, '').replace(/```$/i, '').trim();
const parsed = JSON.parse(cleaned);

const items = Array.isArray(parsed.items)
  ? parsed.items.map((item) => ({
      name: String(item.name ?? 'Alimento'),
      portion_grams: Number(item.portion_grams) || 0,
      calories: Math.round(Number(item.calories) || 0),
      protein_g: Number((Number(item.protein_g) || 0).toFixed(1)),
      carbs_g: Number((Number(item.carbs_g) || 0).toFixed(1)),
      fat_g: Number((Number(item.fat_g) || 0).toFixed(1))
    }))
  : [];

const round1 = (n) => Number((Number(n) || 0).toFixed(1));

const result = {
  ok: true,
  data: {
    is_food: Boolean(parsed.is_food),
    dish_name: String(parsed.dish_name ?? 'Platillo analizado'),
    confidence: Math.min(100, Math.max(0, Math.round(Number(parsed.confidence) || 0))),
    total_calories: Math.round(Number(parsed.total_calories) || 0),
    total_protein_g: round1(parsed.total_protein_g),
    total_carbs_g: round1(parsed.total_carbs_g),
    total_fat_g: round1(parsed.total_fat_g),
    notes: String(parsed.notes ?? 'Estimación orientativa generada por IA.'),
    items
  }
};

return [{ json: result }];
